def aperiodic_autocorr(seq):
    n = len(seq)
    C_sq_sum = 0
    for k in range(1, n):
        Ck = sum(seq[i] * seq[i+k] for i in range(n - k))
        C_sq_sum += Ck * Ck
    return C_sq_sum

def legendre_sequence(p):
    seq = []
    for i in range(p):
        if i == 0:
            seq.append(1)
        else:
            legendre = pow(i, (p-1)//2, p)
            if legendre == p-1:
                seq.append(-1)
            else:
                seq.append(1)
    return seq

